import React, { useEffect, useState } from "react";
import axios from "axios";

const Results = () => {
  const [results, setResults] = useState([]);

  useEffect(() => {
    fetchResults();
  }, []);

  const fetchResults = async () => {
    try {
      const res = await axios.get("http://localhost:5000/results");
      setResults(res.data || []);
    } catch (err) {
      console.error("Error fetching results", err);
    }
  };

  const downloadCSV = () => {
    window.open("http://localhost:5000/download-results", "_blank");
  };

  return (
    <div className="container mt-4">
      {/* Header */}
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h3>Candidate Results</h3>
        <button className="btn btn-primary" onClick={downloadCSV}>
          Download CSV
        </button>
      </div>

      {/* No Results */}
      {results.length === 0 && (
        <p className="text-muted">No results available.</p>
      )}

      {/* Results Cards */}
      {results.map((r, idx) => (
        <div className="card mb-3 shadow-sm" key={idx}>
          <div className="card-body">
            {/* Candidate name / file */}
            <h5 className="card-title">
              {r.filename || `Candidate ${idx + 1}`}
            </h5>

            {/* Score */}
            <p>
              <strong>Score:</strong>{" "}
              <span className="fw-bold">{r.final_score}%</span>
            </p>

            {/* Decision */}
            <p>
              <strong>Status:</strong>{" "}
              <span
                className={
                  r.decision === "Shortlisted"
                    ? "text-success fw-bold"
                    : r.decision === "Review Later"
                      ? "text-warning fw-bold"
                      : "text-danger fw-bold"
                }
              >
                {r.decision}
              </span>
            </p>

            {/* Mandatory Skills Status */}
            {r.rules?.mandatory_skills && (
              <div className="mt-2">
                <strong>Mandatory Skills:</strong>{" "}
                <span
                  className={
                    r.rules.mandatory_skills.status === "pass"
                      ? "text-success"
                      : "text-danger"
                  }
                >
                  {r.rules.mandatory_skills.status === "pass"
                    ? "Passed"
                    : "Failed"}
                </span>
              </div>
            )}

            {/* Missing Mandatory Skills (ALWAYS SHOW IF EXISTS) */}
            {r.rules?.mandatory_skills?.missing?.length > 0 && (
              <div className="mt-2">
                <strong className="text-danger">
                  Missing Mandatory Skills:
                </strong>
                <ul className="mb-0">
                  {r.rules.mandatory_skills.missing.map((skill, i) => (
                    <li key={i}>{skill}</li>
                  ))}
                </ul>
              </div>
            )}

            {/* GitHub Info */}
            {r.rules?.github && (
              <div className="mt-2">
                <strong>GitHub:</strong>{" "}
                {r.rules.github.status === "pass" ? "Provided" : "Not Provided"}
              </div>
            )}

            {/* Skill Overlap Info */}
            {r.rules?.skill_overlap && (
              <div className="mt-2">
                <strong>Skill Match:</strong> {r.rules.skill_overlap.score}%
              </div>
            )}
          </div>
        </div>
      ))}
    </div>
  );
};

export default Results;
